#include <iostream>
using namespace std;

void bubbleSort(int a[], int n, int& comparisons, int& swaps) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            comparisons++;
            if (a[j] > a[j + 1]) {
                swap(a[j], a[j + 1]);
                swaps++;
            }
        }
    }
}

void printArray(int a[], int n) {
    for (int i = 0; i < n; i++) {
        cout << a[i] << " ";
    }
    cout << endl;
}

int main() {
    int a[6] = {5, 1, 4, 2, 8, 3};
    int comparisons = 0;
    int swaps = 0;
    bubbleSort(a, 6, comparisons, swaps);
    printArray(a, 6);
    cout << comparisons << " comparisons, " << swaps << " swaps" << endl;
    return 0;
}
